<script setup lang="ts">
import {reactive,ref,watch} from 'vue'
import {FolderOpen,KeyRound,Check,ShieldCheck,Monitor,Save} from '@lucide/vue'
import type {Config} from '../types'
const props=defineProps<{config:Config;saveConfig:(value:Config)=>Promise<unknown>;saveKey:(value:string)=>Promise<unknown>;pick:(kind:string)=>Promise<string|null>}>()
const values=reactive({...props.config}),key=ref(''),busy=ref(false),message=ref(''),failure=ref('')
watch(()=>props.config,value=>Object.assign(values,value),{deep:true})
async function execute(fn:()=>Promise<unknown>,success:string){busy.value=true;failure.value='';message.value='';try{await fn();message.value=success}catch(e){failure.value=(e as Error).message}finally{busy.value=false}}
async function saveKey(){await execute(async()=>{await props.saveKey(key.value);key.value=''},'Chave armazenada no Windows.');}
async function pick(kind:string,field:'asr_model_path'|'ffmpeg'|'ffprobe'){await execute(async()=>{const result=await props.pick(kind);if(result)values[field]=result},'')}
</script>
<template>
  <header class="page-heading"><div><p class="breadcrumb">Preferências do aplicativo</p><h1>Configurações</h1><p>Seu processamento local. Seu modelo de análise.</p></div></header>
  <div class="settings-grid">
    <form class="settings-main" @submit.prevent="execute(()=>saveConfig({...values}),'Configurações salvas.')">
      <section class="setting-section"><h2><Monitor :size="19"/>Processamento local</h2><p>Transcrição e renderização usam a CPU. Escolha os recursos já instalados.</p><label class="field">Pasta do modelo Whisper<span class="input-action"><input v-model="values.asr_model_path" required/><button type="button" class="icon-button" title="Escolher pasta do modelo" @click="pick('model','asr_model_path')"><FolderOpen :size="18"/></button></span><small>Modelo multilíngue com suporte ao português; arquivos ficam locais.</small></label><div class="field-pair"><label class="field">FFmpeg<span class="input-action"><input v-model="values.ffmpeg" required/><button type="button" class="icon-button" title="Localizar FFmpeg" @click="pick('ffmpeg','ffmpeg')"><FolderOpen :size="17"/></button></span></label><label class="field">ffprobe<span class="input-action"><input v-model="values.ffprobe" required/><button type="button" class="icon-button" title="Localizar ffprobe" @click="pick('ffprobe','ffprobe')"><FolderOpen :size="17"/></button></span></label></div></section>
      <section class="setting-section"><h2>Seleção de trechos</h2><p>A análise com Gemini é opcional e só começa quando você autorizar no projeto.</p><label class="field">Modelo Gemini<input v-model="values.gemini_model" required placeholder="gemini-2.5-flash"/></label><div class="field-pair"><label class="field">Limite de tentativas<input type="number" v-model.number="values.max_calls" min="1" max="100" required/><small>Inclui retries e reparação de JSON.</small></label><label class="field">Janela de análise (segundos)<input type="number" v-model.number="values.window_seconds" min="60" max="1800" required/></label></div><label class="field">Máximo de caracteres por janela<input type="number" v-model.number="values.max_text_chars" min="1000" max="300000" required/></label></section>
      <div class="setting-save"><button class="button primary" :disabled="busy"><Save :size="16"/>Salvar configurações</button></div>
    </form>
    <aside class="settings-aside"><section class="credential-panel"><div class="section-icon"><KeyRound :size="22"/></div><h2>Chave Gemini</h2><span class="status-pill" :data-status="config.gemini_key_configured?'completed':'failed'"><i></i>{{config.gemini_key_configured?'Chave configurada':'Chave não configurada'}}</span><p>Armazenada no Gerenciador de Credenciais do Windows. O aplicativo não exibe a chave salva.</p><label class="field">{{config.gemini_key_configured?'Substituir chave':'Adicionar chave'}}<input type="password" v-model="key" autocomplete="new-password" placeholder="Cole sua chave de API"/></label><button type="button" class="button secondary full" data-action="save-key" :disabled="busy||!key.trim()" @click="saveKey"><KeyRound :size="16"/>Salvar chave</button></section><section class="local-info"><ShieldCheck :size="23"/><h3>O vídeo fica aqui</h3><p>O provedor recebe apenas a transcrição em texto. Vídeo, áudio e frames não são enviados.</p><div class="resource-line"><Check :size="15"/>{{config.asr_available?'Modelo local disponível':'Modelo local não encontrado'}}</div><div class="resource-line"><Check :size="15"/>{{config.tools_available?'Ferramentas de vídeo disponíveis':'Localize FFmpeg e ffprobe'}}</div></section></aside>
  </div><p v-if="message" class="notice success" role="status">{{message}}</p><p v-if="failure" class="notice error" role="alert">{{failure}}</p>
</template>
